# SQUAD ANALYSIS · all records sourced from the supplied SofaScore workbook.
@st.cache_data
def load_players():
    import pandas as pd
    path = BASE / "data" / "czech_fnl_players.csv"
    if not path.exists():
        return None
    data = pd.read_csv(path, encoding="utf-8-sig")
    for field in ["Goles", "Asistencias", "Minutos jugados", "Partidos jugados", "Titularidades",
                  "Tiros totales", "Tiros a puerta", "Pases clave", "Regates completados",
                  "Duelos totales ganados", "Despejes", "Pases precisos %"]:
        data[field] = pd.to_numeric(data[field], errors="coerce").fillna(0)
    return data

def player_key(name):
    normalized = unicodedata.normalize("NFKD", str(name))
    return "_".join("".join(ch for ch in normalized if not unicodedata.combining(ch)).lower().split())

def player_photo(name):
    image_path = BASE / "assets" / "players" / (player_key(name) + ".png")
    if not image_path.exists():
        return None
    return "data:image/png;base64," + base64.b64encode(image_path.read_bytes()).decode("ascii")

def photo_html(name, size=48):
    uri = player_photo(name)
    if uri:
        return f'<img src="{uri}" alt="Player portrait" style="width:{size}px;height:{size}px;object-fit:cover;object-position:top;border-radius:9px;background:#e9eef2;border:1px solid #34445a;flex-shrink:0">'
    return f'<div title="No player photo available" style="width:{size}px;height:{size}px;display:flex;align-items:center;justify-content:center;background:#22334b;border:1px solid #42536a;border-radius:9px;color:#b7c7db;flex-shrink:0;font-size:{max(19,size//2)}px">♟</div>'

players = load_players()
with sections[1]:
    st.markdown('<div class="section-title">Squad Analysis</div><div class="muted">SFC Opava · 2026/27 · SofaScore performance data</div>', unsafe_allow_html=True)
    if players is None:
        st.warning("Missing data/czech_fnl_players.csv — copy the supplied data folder alongside app.py.")
    else:
        squad = players[players["Equipo"].astype(str).str.contains("Opava", case=False, na=False)].copy()
        if squad.empty:
            st.warning("No SFC Opava players found in the dataset.")
        else:
            squad = squad.sort_values("Minutos jugados", ascending=False)
            st.write("")
            stats = [("SQUAD PLAYERS", len(squad)), ("TOTAL MINUTES", f'{int(squad["Minutos jugados"].sum()):,}'),
                     ("GOALS", int(squad["Goles"].sum())), ("ASSISTS", int(squad["Asistencias"].sum()))]
            for c, (name, value) in zip(st.columns(4), stats):
                with c:
                    st.markdown(f'<div class="info-card"><div class="info-label">{name}</div><div class="info-value">{value}</div></div>', unsafe_allow_html=True)
            st.write("")
            field_col, list_col = st.columns([1.02, 1.35], gap="large")
            # Data provides only POR / DEF / MED / DEL; individual defensive and midfield roles cannot be verified.
            def line_players(position, n):
                return squad[squad["Posición"] == position].head(n).to_dict("records")
            formation = [("DEL", 2), ("MED", 3), ("DEF", 5), ("POR", 1)]
            with field_col:
                st.markdown('<div class="panel-title">Estimated XI · 5-3-2</div>', unsafe_allow_html=True)
                st.caption("Highest minutes by broad position. An illustrative 5-3-2, not the club’s verified most-used starting XI.")
                pitch = ['<div class="squad-pitch">']
                for position, count in formation:
                    group = line_players(position, count)
                    pitch.append('<div class="pitch-row">')
                    for person in group:
                        name = html.escape(str(person["Jugador"]))
                        mins = int(person["Minutos jugados"])
                        pitch.append(f'<div class="pitch-player">{photo_html(person["Jugador"], 45)}<span class="shirt">{position}</span><strong>{name}</strong><small>{mins:,} min</small></div>')
                    pitch.append('</div>')
                pitch.append('</div>')
                st.markdown(''.join(pitch), unsafe_allow_html=True)
                st.caption("Positions in the source: POR, DEF, MED and DEL. Specific roles (CB, wing-back, etc.) are not provided.")
            with list_col:
                st.markdown('<div class="panel-title">First-team squad</div>', unsafe_allow_html=True)
                role = st.selectbox("Filter by position", ["All", "POR", "DEF", "MED", "DEL"], key="squad_role")
                listing = squad if role == "All" else squad[squad["Posición"] == role]
                listing = listing[["Jugador", "Posición", "Partidos jugados", "Titularidades", "Minutos jugados", "Goles", "Asistencias"]].rename(columns={
                    "Jugador":"Player", "Posición":"Pos", "Partidos jugados":"Apps", "Titularidades":"Starts",
                    "Minutos jugados":"Min", "Goles":"Goals", "Asistencias":"Assists"})
                st.dataframe(listing, hide_index=True, width="stretch", height=390)
                st.caption("Player portraits · All available squad images; missing images use a silhouette.")
                portraits = listing["Player"].tolist()
                for start in range(0, len(portraits), 4):
                    for col, player_name in zip(st.columns(4), portraits[start:start+4]):
                        with col:
                            st.markdown(f'<div style="background:#111e31;border:1px solid #293b53;border-radius:10px;padding:9px;text-align:center;min-height:123px;display:flex;align-items:center;flex-direction:column;gap:7px">{photo_html(player_name, 65)}<span style="color:#f1f6fc;font-size:11px;font-weight:600">{html.escape(str(player_name))}</span></div>', unsafe_allow_html=True)
            st.write("")
            st.markdown('<div class="panel-title">Squad Leaders</div>', unsafe_allow_html=True)
            leaders = [("TOP SCORER", "Goles", "goals"), ("TOP ASSIST PROVIDER", "Asistencias", "assists"),
                       ("MOST PLAYED", "Minutos jugados", "minutes"), ("MOST SHOTS", "Tiros totales", "shots"),
                       ("MOST KEY PASSES", "Pases clave", "key passes"), ("MOST DUELS WON", "Duelos totales ganados", "duels won")]
            for start in [0, 3]:
                cols = st.columns(3)
                for col, (title, metric, unit) in zip(cols, leaders[start:start+3]):
                    best = squad.sort_values([metric, "Minutos jugados"], ascending=False).iloc[0]
                    with col:
                        st.markdown(f'<div class="leader-card"><div style="float:right">{photo_html(best["Jugador"], 72)}</div><div class="info-label">{title}</div><div class="leader-name">{html.escape(str(best["Jugador"]))}</div><div class="leader-value">{int(best[metric]):,} <span>{unit}</span></div></div>', unsafe_allow_html=True)
            st.markdown('<div class="panel-title">Explore Every Squad Leader</div>', unsafe_allow_html=True)
            st.caption("Choose any available SofaScore statistic to identify the squad leader and the top five players. Percentage leaders require at least one recorded relevant action when the corresponding volume metric is available.")
            metric_labels = {
                "Goles": "Goals", "Tiros totales": "Total Shots", "Tiros a puerta": "Shots on Target",
                "Regates completados": "Completed Dribbles", "Regateos con éxito %": "Dribble Success %",
                "Despejes": "Clearances", "Regateado": "Times Dribbled Past",
                "Asistencias": "Assists", "Pases clave": "Key Passes", "Pases totales": "Total Passes",
                "Pases precisos": "Accurate Passes", "Pases precisos %": "Pass Accuracy %",
                "Pases precisos en el tercio final": "Accurate Final Third Passes",
                "Cruces precisos": "Accurate Crosses", "Cruces precisos %": "Cross Accuracy %",
                "Duelos totales ganados": "Duels Won", "Duelos totales ganados %": "Duels Won %",
                "Duelos aéreos ganados": "Aerial Duels Won", "Duelos aéreos ganados %": "Aerial Duels Won %",
                "Minutos jugados": "Minutes Played", "Partidos jugados": "Appearances",
                "Titularidades": "Starts"
            }
            available_metrics = [c for c in metric_labels if c in squad.columns]
            selector_col, top_col = st.columns([3, 1])
            with selector_col:
                chosen = st.selectbox("Statistic", available_metrics, format_func=lambda c: metric_labels[c], key="all_squad_leaders_stat")
            with top_col:
                top_n = st.selectbox("Show top", [3, 5, 10, "All"], index=1, key="all_squad_leaders_count")
            ranked = squad.copy()
            ranked[chosen] = pd.to_numeric(ranked[chosen], errors="coerce")
            ranked = ranked.dropna(subset=[chosen])
            # Avoid treating a 100% rate from no attempts as a leader.
            percentage_volume = {"Regateos con éxito %": "Regates completados", "Cruces precisos %": "Cruces precisos",
                                 "Duelos totales ganados %": "Duelos totales ganados", "Duelos aéreos ganados %": "Duelos aéreos ganados",
                                 "Pases precisos %": "Pases totales"}
            if chosen in percentage_volume and percentage_volume[chosen] in ranked.columns:
                volume = pd.to_numeric(ranked[percentage_volume[chosen]], errors="coerce").fillna(0)
                ranked = ranked.loc[volume > 0]
            ranked = ranked.sort_values([chosen, "Minutos jugados"], ascending=[False, False])
            if ranked.empty:
                st.info("No eligible squad players have recorded values for this statistic.")
            else:
                leader = ranked.iloc[0]
                is_pct = chosen.endswith("%")
                def stat_value(v):
                    if is_pct:
                        # The CSV can store ratios as 0–1 rather than 0–100.
                        return f"{float(v) * (100 if ranked[chosen].max() <= 1 else 1):.1f}%"
                    return f"{float(v):,.1f}" if float(v) % 1 else f"{int(v):,}"
                st.markdown(f'<div class="leader-card" style="display:flex;align-items:center;gap:20px;min-height:120px">{photo_html(leader["Jugador"], 88)}<div><div class="info-label">{html.escape(metric_labels[chosen].upper())} · SQUAD LEADER</div><div class="leader-name">{html.escape(str(leader["Jugador"]))}</div><div class="leader-value">{stat_value(leader[chosen])}</div></div></div>', unsafe_allow_html=True)
                shown = ranked if top_n == "All" else ranked.head(top_n)
                for place, (_, player) in enumerate(shown.iterrows(), 1):
                    st.markdown(f'<div style="display:flex;align-items:center;gap:12px;background:#111e31;border:1px solid #293b53;border-radius:9px;padding:8px 12px;margin-bottom:6px"><span style="color:#ffea00;font-weight:700;min-width:25px">#{place}</span>{photo_html(player["Jugador"], 40)}<span style="color:white;flex:1;font-weight:600">{html.escape(str(player["Jugador"]))}</span><span style="color:#ffea00;font-weight:700">{stat_value(player[chosen])}</span></div>', unsafe_allow_html=True)
            with st.expander("View leaders across all available statistics"):
                all_rows = []
                for metric in available_metrics:
                    values = squad.copy()
                    values[metric] = pd.to_numeric(values[metric], errors="coerce")
                    values = values.dropna(subset=[metric])
                    if metric in percentage_volume and percentage_volume[metric] in values.columns:
                        values = values.loc[pd.to_numeric(values[percentage_volume[metric]], errors="coerce").fillna(0) > 0]
                    if not values.empty:
                        best = values.sort_values([metric, "Minutos jugados"], ascending=False).iloc[0]
                        val = float(best[metric])
                        value_str = f"{val * (100 if values[metric].max() <= 1 else 1):.1f}%" if metric.endswith("%") else (f"{val:,.1f}" if val % 1 else f"{int(val):,}")
                        all_rows.append({"Statistic": metric_labels[metric], "Leader": best["Jugador"], "Value": value_str})
                st.dataframe(pd.DataFrame(all_rows), hide_index=True, width="stretch")
            st.caption("Source: SofaScore player statistics supplied for this project. Discipline metrics are unavailable in the dataset. 'Times Dribbled Past' is a negative statistic; the highest value is not necessarily best.")

# LEAGUE PERFORMANCE · BeSoccer 2026/27, Matchday 12 (user-supplied screenshots).
# Kept separate from SofaScore player-level data.
with sections[1]:
    st.write("")
    st.markdown('<div class="section-title">League Performance</div><div class="muted">Chance Národní Liga · 2026/27 · Matchday 12 · Source: BeSoccer</div>', unsafe_allow_html=True)
    standings_path = BASE / "data" / "league_standings_besoccer_md12.csv"
    if not standings_path.is_file():
        st.warning("League standings file missing from data/.")
    else:
        import pandas as pd
        league = pd.read_csv(standings_path, encoding="utf-8-sig")
        split = st.segmented_control("Standings view", ["Overall", "Home", "Away"], default="Overall", key="league_split")
        view = league.loc[league["Split"] == split].sort_values("Rank").copy()
        view["GD"] = view["GF"] - view["GA"]
        opava = view.loc[view["Team"] == "SFC Opava"].iloc[0]
        a, b, c, d = st.columns(4)
        for col, label, value in [(a, "POSITION", f'{int(opava["Rank"])}/16'),
                                  (b, "POINTS", int(opava["Points"])),
                                  (c, "GOALS FOR", int(opava["GF"])),
                                  (d, "GOALS AGAINST", int(opava["GA"]))]:
            with col:
                st.markdown(f'<div class="info-card"><div class="info-label">{label}</div><div class="info-value">{value}</div></div>', unsafe_allow_html=True)
        st.write("")
