# Inline scouting filters: no modal, all controls sit above the results table.
if "market_filter_reset" not in st.session_state:
    st.session_state.market_filter_reset = 0

def market_numeric(series, metric):
    values = pd.to_numeric(series, errors="coerce")
    if metric in PERCENT_METRICS and values.dropna().size and values.dropna().max() <= 1:
        values = values * 100
    return values

def market_filter_data(data, filt):
    result = data.copy()
    if filt["positions"]:
        result = result[result["Posición"].isin(filt["positions"])]
    if filt["clubs"]:
        result = result[result["Equipo"].isin(filt["clubs"])]
    if filt["exclude_opava"]:
        result = result[~result["Equipo"].astype(str).str.contains("Opava", case=False, na=False)]
    result = result[pd.to_numeric(result["Minutos jugados"], errors="coerce") >= filt["min_minutes"]]
    for cond in filt["conditions"]:
        metric, op, threshold = cond["metric"], cond["op"], cond["value"]
        if metric not in result.columns:
            continue
        v = market_numeric(result[metric], metric)
        if op == ">=": mask = v >= threshold
        elif op == "<=": mask = v <= threshold
        elif op == ">": mask = v > threshold
        elif op == "<": mask = v < threshold
        else: mask = v == threshold
        result = result[mask.fillna(False)]
    return result

