# PLAYER COMPARISON · two-player, source-grounded scouting comparison.
import math

COMPARISON_GROUPS = {
    "Attacking": ["Goles", "Asistencias", "Tiros totales", "Tiros a puerta", "Pases clave", "Regates completados"],
    "Passing": ["Pases totales", "Pases precisos", "Pases precisos %", "Pases precisos en el tercio final", "Cruces precisos", "Cruces precisos %"],
    "Duels & Defending": ["Duelos totales ganados", "Duelos totales ganados %", "Duelos aéreos ganados", "Duelos aéreos ganados %", "Despejes", "Regateado"],
}

def comparison_value(person, metric, per90=False):
    raw = pd.to_numeric(pd.Series([person.get(metric)]), errors="coerce").iloc[0]
    if pd.isna(raw):
        return float("nan")
    if metric in PERCENT_METRICS:
        return float(raw * 100 if raw <= 1 else raw)
    if per90:
        mins = pd.to_numeric(pd.Series([person.get("Minutos jugados")]), errors="coerce").iloc[0]
        return float(raw * 90 / mins) if pd.notna(mins) and mins > 0 else float("nan")
    return float(raw)

def comparison_radar(labels, left, right):
    # Self-contained SVG: no new Python dependency required.
    n = len(labels)
    cx, cy, radius = 260, 205, 135
    def xy(i, val):
        theta = -math.pi / 2 + 2 * math.pi * i / n
        return cx + radius * val * math.cos(theta), cy + radius * val * math.sin(theta)
    def points(vals):
        return " ".join(f"{xy(i, max(0.0, min(1.0, v)))[0]:.1f},{xy(i, max(0.0, min(1.0, v)))[1]:.1f}" for i, v in enumerate(vals))
    pieces = ['<svg viewBox="0 0 520 440" xmlns="http://www.w3.org/2000/svg" style="width:100%;max-width:600px;display:block;margin:auto">']
    for level in (.25,.5,.75,1):
        pieces.append(f'<polygon points="{points([level]*n)}" fill="none" stroke="#40516a" stroke-width="1"/>')
    for i,label in enumerate(labels):
        x,y=xy(i,1)
        pieces.append(f'<line x1="{cx}" y1="{cy}" x2="{x:.1f}" y2="{y:.1f}" stroke="#40516a"/>')
        tx,ty=xy(i,1.27)
        words=html.escape(label)
        pieces.append(f'<text x="{tx:.1f}" y="{ty:.1f}" text-anchor="middle" dominant-baseline="middle" fill="#d8e5f5" font-size="11">{words}</text>')
    pieces.append(f'<polygon points="{points(left)}" fill="#ffea00" fill-opacity=".19" stroke="#ffea00" stroke-width="2.5"/>')
    pieces.append(f'<polygon points="{points(right)}" fill="#55b9f5" fill-opacity=".19" stroke="#55b9f5" stroke-width="2.5"/>')
    pieces.append('</svg>')
    return ''.join(pieces)

